
import {icons} from './icons.js';
import {fileError,canReview,escapeText as esc} from './campaign-model.js';
const icon=n=>icons[n]||'';
let root=null,step=0,name='A little nudge. A big first step.',channel='Email',audience='New users · Not activated',assets=[],errors=[],serial=0,launchTimer=null,launching=false;
const timers=new Set();
export function leaveCampaign(){root=null;if(launchTimer){clearTimeout(launchTimer);launchTimer=null;launching=false;}}
export function resetCampaign(){for(const a of assets)if(a.blob)URL.revokeObjectURL(a.url);for(const t of timers)clearTimeout(t);timers.clear();clearTimeout(launchTimer);launchTimer=null;assets=[];errors=[];step=0;launching=false;channel='Email';audience='New users · Not activated';name='A little nudge. A big first step.';}
export function mountCampaign(target){root=target;draw();}
const bytes=n=>n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
function add(files){errors=[];for(const f of files){const error=fileError(f,assets);if(error){errors.push(f.name+': '+error);continue;}const isImage=/\.(png|jpe?g|webp|gif)$/i.test(f.name);const a={id:++serial,name:f.name,size:f.size,image:isImage,url:URL.createObjectURL(f),blob:true,ready:false};assets.push(a);const t=setTimeout(()=>{a.ready=true;timers.delete(t);if(root&&step===1)draw();},900);timers.add(t);}draw();}
function sample(){errors=[];if(assets.some(a=>a.sample))return;if(assets.length>=8){errors=['You can add up to 8 assets.'];draw();return;}const a={id:++serial,name:'welcome-to-your-next.png',size:184320,image:true,url:'campaign-art.svg',sample:true,ready:false};assets.push(a);draw();const t=setTimeout(()=>{a.ready=true;timers.delete(t);if(root&&step===1)draw();},900);timers.add(t);}
function preview(){const a=assets.find(a=>a.image&&a.ready);return '<div class="message-preview"><div class="message-brand"><span class="workspace-avatar">P</span><div>PayZapp<small>Your everyday, made rewarding.</small></div></div>'+(a?'<img class="creative-preview" src="'+esc(a.url)+'" alt="Selected campaign creative">':'<div class="creative-placeholder">'+icon('image')+'<span>Your creative goes here</span></div>')+'<div class="message-copy"><h3>A great start is just one tap away.</h3><p>Discover a simpler way to pay. Complete your setup and make your first moment count.</p><span class="preview-cta">Let’s get started '+icon('arrow-right')+'</span></div></div>';}
function rows(){return assets.map(a=>'<div class="asset-row"><div class="asset-thumb">'+(a.image?'<img src="'+esc(a.url)+'" alt="">':icon('file-text'))+'</div><div class="asset-info"><strong>'+esc(a.name)+'</strong><small>'+bytes(a.size)+' · '+(a.ready?'Ready to use':'Preparing local preview…')+'</small>'+(!a.ready?'<div class="asset-progress"><span></span></div>':'')+'</div><span class="asset-ready">'+(a.ready?icon('circle-check'):'')+'</span><button class="remove-asset" data-remove="'+a.id+'" aria-label="Remove '+esc(a.name)+'">'+icon('x')+'</button></div>').join('');}
function draw(){
 if(!root)return;
 if(step===3){root.innerHTML='<section class="launch-success"><div class="success-orbit"><span>'+icon('check')+'</span><i></i><b></b></div><div class="eyebrow">READY FOR YOUR NEXT CHAPTER</div><h2>Your campaign is ready to go.</h2><p><strong>'+esc(name)+'</strong> is set up with '+assets.length+' creative asset'+(assets.length===1?'':'s')+'.</p><div class="success-receipt"><div><span>Channel</span><strong>'+esc(channel)+'</strong></div><div><span>Audience</span><strong>'+esc(audience)+'</strong></div><div><span>Status</span><strong class="positive">Demo launch complete</strong></div></div><p class="local-note">Simulation complete. No campaign was sent and no files left this device.</p><button class="button primary" id="new-campaign">'+icon('plus')+'Create another campaign</button><button class="text-button" id="back-review">Back to review</button></section>';root.querySelector('#new-campaign').onclick=()=>{resetCampaign();draw();};root.querySelector('#back-review').onclick=()=>{step=2;draw();};return;}
 root.innerHTML='<div class="campaign-steps">'+['Campaign details','Creative assets','Review & launch'].map((label,i)=>'<div class="'+(i===step?'current':i<step?'done':'')+'"><span>'+(i<step?icon('check'):i+1)+'</span>'+label+'</div>').join('')+'</div><div class="campaign-layout"><section class="campaign-panel">'+
 (step===0?'<div class="panel-heading"><span class="panel-icon">'+icon('megaphone')+'</span><div><h2>Make it worth opening.</h2><p>Start with the essentials. Then bring your message to life.</p></div></div><div class="campaign-fields"><label for="campaign-name">Campaign name</label><input id="campaign-name" maxlength="90" value="'+esc(name)+'" placeholder="Give your campaign a name"><small>Only visible to your team.</small><label>Choose your channel</label><div class="channel-options">'+['Email','In-app message','Web push'].map(x=>'<button class="'+(channel===x?'selected':'')+'" data-channel="'+x+'">'+icon(x==='Email'?'mail':x==='Web push'?'send':'layers')+'<strong>'+x+'</strong><span>'+(x==='Email'?'Meet them in their inbox':x==='Web push'?'A timely reason to return':'Connect in the moment')+'</span></button>').join('')+'</div><label for="campaign-audience">Who would you like to reach?</label><select id="campaign-audience">'+['New users · Not activated','All active users','Returning users'].map(x=>'<option '+(x===audience?'selected':'')+'>'+x+'</option>').join('')+'</select></div>':
 step===1?'<div class="panel-heading"><span class="panel-icon">'+icon('image')+'</span><div><h2>A little creative. A lot of possibility.</h2><p>Add the assets that will make your campaign stand out.</p></div></div><div id="dropzone" class="dropzone"><div class="upload-illustration" aria-hidden="true"><div class="upload-halo"></div><div class="art-card back-card">'+icon('file-text')+'<i></i><i></i></div><div class="art-card image-card"><div class="tiny-sun"></div><div class="tiny-mountain"></div></div><div class="upload-emblem">'+icon('cloud-upload')+'</div><span class="upload-spark spark-one"></span><span class="upload-spark spark-two"></span></div><h3>Drop something brilliant here.</h3><p>Drag & drop your files, or choose them from your device.</p><button class="button primary" id="browse">'+icon('folder-up')+'Choose files</button><input type="file" id="asset-files" multiple accept=".png,.jpg,.jpeg,.webp,.gif,.pdf,.doc,.docx" hidden><span class="format-note">PNG, JPG, WebP, GIF, PDF, DOC, DOCX · Up to 10 MB each</span></div><div class="upload-under"><span>'+icon('shield-check')+'Files stay on this device</span><button class="text-button" id="sample">'+icon('plus')+'Use a sample creative</button></div><div class="upload-errors" role="alert">'+errors.map(e=>'<p>'+esc(e)+'</p>').join('')+'</div>'+(assets.length?'<div class="assets-heading"><strong>Campaign assets</strong><span>'+assets.length+' / 8 files</span></div><div class="asset-list">'+rows()+'</div>':''):
 '<div class="panel-heading"><span class="panel-icon">'+icon('rocket')+'</span><div><h2>One last look. Then lift off.</h2><p>Everything you need for your next customer connection.</p></div></div><div class="review-details"><div><span>Campaign name</span><strong>'+esc(name)+'</strong></div><div><span>Channel</span><strong>'+esc(channel)+'</strong></div><div><span>Audience</span><strong>'+esc(audience)+'</strong></div><div><span>Delivery</span><strong>Immediately · Demo only</strong></div></div><div class="assets-heading"><strong>Creative assets</strong><span>'+assets.length+' ready</span></div><div class="asset-list">'+rows()+'</div><div class="demo-callout">'+icon('shield-check')+'This launch is a simulation. Nothing will be sent to customers.</div>')+
 '<div class="campaign-actions"><button id="campaign-back" class="button" '+(step===0||launching?'disabled':'')+'>'+icon('arrow-left')+'Back</button><span>Step '+(step+1)+' of 3</span><button id="campaign-next" class="button primary" '+(step===1&&!canReview(assets)||launching?'disabled':'')+'>'+(launching?'Launching demo…':step===0?'Continue to assets':step===1?'Review campaign':'Launch demo campaign')+icon(step===2?'rocket':'arrow-right')+'</button></div></section><aside class="creative-sidebar"><div class="preview-label">'+icon('image')+'CREATIVE PREVIEW<span>'+esc(channel)+'</span></div>'+preview()+'<div class="preview-advice">'+icon('sparkles')+'<div><strong>Good creative starts a conversation.</strong><p>Keep the message clear, the visual memorable, and the next step simple.</p></div></div><p class="local-note">Illustrative message preview. Documents are attached assets and are not rendered here.</p></aside></div>';
 root.querySelector('#campaign-back').onclick=()=>{if(launching)return;step--;errors=[];draw();};
 root.querySelector('#campaign-next').onclick=()=>{if(step===0){const input=root.querySelector('#campaign-name');name=input.value.trim();if(!name){input.setCustomValidity('Enter a campaign name.');input.reportValidity();return;}step=1;draw();}else if(step===1&&canReview(assets)){step=2;draw();}else if(step===2&&!launching&&canReview(assets)){launching=true;draw();launchTimer=setTimeout(()=>{launching=false;launchTimer=null;step=3;draw();},1000);}};
 root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(launching)return;const a=assets.find(a=>a.id===+b.dataset.remove);if(a?.blob)URL.revokeObjectURL(a.url);assets=assets.filter(a=>a!==a);if(step===2&&!assets.length)step=1;draw();});
 if(step===0){root.querySelector('#campaign-name').oninput=e=>{name=e.target.value;e.target.setCustomValidity('');};root.querySelector('#campaign-audience').onchange=e=>audience=e.target.value;root.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{channel=b.dataset.channel;draw();});}
 if(step===1){const zone=root.querySelector('#dropzone'),input=root.querySelector('#asset-files');root.querySelector('#browse').onclick=()=>input.click();input.onchange=()=>add([...input.files]);root.querySelector('#sample').onclick=sample;let depth=0;zone.ondragenter=e=>{e.preventDefault();depth++;zone.classList.add('dragging');};zone.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';};zone.ondragleave=()=>{if(--depth<=0)zone.classList.remove('dragging');};zone.ondrop=e=>{e.preventDefault();depth=0;zone.classList.remove('dragging');add([...e.dataTransfer.files]);};}
}
window.addEventListener('beforeunload',()=>{for(const a of assets)if(a.blob)URL.revokeObjectURL(a.url);});
